pages = $router({
  "/": Home(),
  "/orders/:id": OrderDetail(params.id),
  default: NotFound()
})

function Home() {
  return Column([
    PageHeader("Orders"),
    NavLink("Open order 42", { to: "/orders/42" })
  ])
}

function OrderDetail(id) {
  return Column([
    PageHeader(`Order ${id}`),
    Card([Text("Captured from the :id segment.")])
  ])
}

function NotFound() {
  return EmptyState("No such page", { icon: "compass", description: route.path })
}

